import React from 'react';
import { CityGraph, TrafficLevel } from '../types';

interface Props {
  graph: CityGraph;
  highlightPath: string[];
}

const trafficColors: Record<TrafficLevel, string> = {
  Low: '#22c55e',
  Moderate: '#eab308',
  Heavy: '#ef4444',
  Blocked: '#94a3b8',
};

const GraphVisualization: React.FC<Props> = ({ graph, highlightPath }) => {
  const getNodeColor = (type: string) => {
    switch(type) {
      case 'Ambulance': return '#3b82f6';
      case 'Patient': return '#eab308';
      case 'Hospital': return '#22c55e';
      default: return '#64748b';
    }
  };

  const isEdgeInPath = (from: string, to: string) => {
    for (let i = 0; i < highlightPath.length - 1; i++) {
      if (
        (highlightPath[i] === from && highlightPath[i + 1] === to) ||
        (highlightPath[i] === to && highlightPath[i + 1] === from)
      ) {
        return true;
      }
    }
    return false;
  };

  return (
    <svg width="100%" height="400" viewBox="0 0 1000 600" style={{ background: '#f8fafc', borderRadius: '8px', border: '1px solid #e2e8f0' }}>
      {/* Edges */}
      {graph.edges.map((edge, idx) => {
        const fromNode = graph.nodes.find(n => n.id === edge.from)!;
        const toNode = graph.nodes.find(n => n.id === edge.to)!;
        const inPath = isEdgeInPath(edge.from, edge.to);

        return (
          <line
            key={idx}
            x1={fromNode.x}
            y1={fromNode.y}
            x2={toNode.x}
            y2={toNode.y}
            stroke={inPath ? '#3b82f6' : trafficColors[edge.traffic]}
            strokeWidth={inPath ? 4 : 2}
            strokeDasharray={edge.traffic === 'Blocked' ? '6,6' : '0'}
            strokeLinecap="round"
          />
        );
      })}
      {/* Nodes */}
      {graph.nodes.map(node => (
        <g key={node.id}>
          <circle
            cx={node.x}
            cy={node.y}
            r={24}
            fill={getNodeColor(node.type)}
            stroke="white"
            strokeWidth="2"
          />
          <text x={node.x} y={node.y + 5} textAnchor="middle" fill="white" fontSize="14" fontWeight="600" fontFamily="Inter">
            {node.id}
          </text>
          <text x={node.x} y={node.y + 42} textAnchor="middle" fill="#64748b" fontSize="12" fontWeight="500" fontFamily="Inter">
            {node.name}
          </text>
        </g>
      ))}
      {/* Legend */}
      <g transform="translate(20, 20)">
        <rect x="0" y="0" width="130" height="110" fill="white" rx="6" stroke="#e2e8f0" strokeWidth="1" />
        <text x="12" y="22" fontSize="11" fontWeight="600" fill="#475569">Node Types</text>
        <circle cx="18" cy="42" r="6" fill="#3b82f6" />
        <text x="32" y="46" fontSize="10" fill="#64748b">Start</text>
        <circle cx="18" cy="62" r="6" fill="#eab308" />
        <text x="32" y="66" fontSize="10" fill="#64748b">Patient</text>
        <circle cx="18" cy="82" r="6" fill="#22c55e" />
        <text x="32" y="86" fontSize="10" fill="#64748b">Hospital</text>
        <circle cx="18" cy="102" r="6" fill="#64748b" />
        <text x="32" y="106" fontSize="10" fill="#64748b">Normal</text>
      </g>
      {/* Traffic Legend */}
      <g transform="translate(850, 20)">
        <rect x="0" y="0" width="130" height="95" fill="white" rx="6" stroke="#e2e8f0" strokeWidth="1" />
        <text x="12" y="22" fontSize="11" fontWeight="600" fill="#475569">Traffic Levels</text>
        <line x1="14" y1="40" x2="32" y2="40" stroke="#22c55e" strokeWidth="2" strokeLinecap="round" />
        <text x="40" y="44" fontSize="10" fill="#64748b">Low</text>
        <line x1="14" y1="60" x2="32" y2="60" stroke="#eab308" strokeWidth="2" strokeLinecap="round" />
        <text x="40" y="64" fontSize="10" fill="#64748b">Moderate</text>
        <line x1="14" y1="80" x2="32" y2="80" stroke="#ef4444" strokeWidth="2" strokeLinecap="round" />
        <text x="40" y="84" fontSize="10" fill="#64748b">Heavy</text>
        <line x1="14" y1="100" x2="32" y2="100" stroke="#94a3b8" strokeWidth="2" strokeLinecap="round" strokeDasharray="3,3" />
        <text x="40" y="104" fontSize="10" fill="#64748b">Blocked</text>
      </g>
    </svg>
  );
};

export default GraphVisualization;
